changeSet.sql:
INSERT INTO reminder_creation(id,user_id,device_id,title,trigger_at,recurrence,seconds,created_at)
 SELECT id,user_id,device_id,title,CASE WHEN initial_seconds>0 THEN NULL ELSE requested_at END,'once',CASE WHEN initial_seconds>0 THEN initial_seconds ELSE NULL END,created_at FROM user_reminder WHERE task_id IS NULL AND plan_id IS NULL;
INSERT IGNORE INTO reminder_creation(id,user_id,device_id,title,trigger_at,recurrence,seconds,created_at)
 SELECT id,user_id,device_id,title,initial_at,recurrence,NULL,created_at FROM reminder_plan WHERE task_enabled=false;
